<script setup>
import { ref, reactive, computed, onMounted, onBeforeUnmount,watch } from 'vue'
import { basicSlots, viewNames, framingNames } from './characterLibraryModel.js'
const props=defineProps({api:Function,initialCharacterId:Number});const emit=defineEmits(['changed'])
const projects=ref([]),people=ref([]),person=ref(null),state=ref(null),error=ref(''),busy=ref(false),zoom=ref(null),human=ref(false),note=ref(''),identity=ref(null),outfit=ref(null),taskId=ref(null),view=ref('front'),framing=ref('closeUp'),slot=ref('front:closeUp'),repairOf=ref(null),reason=ref(''),seed=ref(2026102701),label=ref('基础造型'),choices=reactive({})
const form=reactive({projectId:null,name:'',ageSetting:'',faceFeatures:'',hair:'',bodyRatio:'',clothes:'',fixedPrompt:'',shoes:'',immutableTraits:''})
const keys=['name','ageSetting','faceFeatures','hair','bodyRatio','clothes','shoes','fixedPrompt','immutableTraits']
const labels={name:'姓名',ageSetting:'年龄设定',faceFeatures:'脸部特征',hair:'发型发色',bodyRatio:'体型比例',clothes:'基础服装',shoes:'鞋子',fixedPrompt:'固定外貌描述（不含裤装鞋子）',immutableTraits:'禁改特征'}
const refs=computed(()=>state.value?.references||[])
const generationKeys=new Map()
const adjustment=ref('')
const complete=computed(()=>basicSlots.every(([v,f])=>choices[v+':'+f]))
const media=p=>'/api/media?assetPath='+encodeURIComponent(p)
function candidateLabel(r){const [v,f]=r.kind.split('-');return `${viewNames[v]||v} · ${framingNames[f]||'旧版用途'} · #${r.id}`}
async function act(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(){[projects.value,people.value]=await Promise.all([props.api('/api/projects'),props.api('/api/characters')]);if(!form.projectId)form.projectId=projects.value[0]?.id}
async function selected(){if(!person.value){state.value=null;return}state.value=await props.api('/api/character-workshop/'+person.value);const c=state.value.character;for(const k of keys)form[k]=c[k]||'';form.projectId=c.projectId;const m=typeof c.metadataJson==='string'?JSON.parse(c.metadataJson):c.metadataJson||{};form.shoes=m.referenceStudio?.shoes||'';form.immutableTraits=m.referenceStudio?.immutableTraits||'';identity.value=state.value.anchors?.payload.identity?.id||null;outfit.value=state.value.anchors?.payload.outfit?.id||null;Object.keys(choices).forEach(k=>delete choices[k])}
async function refresh(){if(person.value)state.value=await props.api('/api/character-workshop/'+person.value)}
async function save(){await act(async()=>{if(!form.projectId||keys.some(k=>!form[k]?.trim()))throw new Error('请选择所属项目并补齐全部人物设定，包括鞋子与禁改特征');const original=state.value?.character;const metadata=original?.metadataJson?JSON.parse(original.metadataJson):{};metadata.referenceStudio={...metadata.referenceStudio,shoes:form.shoes,immutableTraits:form.immutableTraits};const body={...original,...form,metadata};const r=await props.api(person.value?'/api/characters/'+person.value:'/api/characters',{method:person.value?'PUT':'POST',body:JSON.stringify(body)});if(!person.value)person.value=r.id;await load();await selected();emit('changed')})}
async function generate(kind){await act(async()=>{const [v,f]=slot.value.split(':');const request={characterId:person.value,kind,view:kind==='slot'?v:'front',framing:kind==='identity'?'closeUp':kind==='outfit'?'fullBody':f,seed:Number(seed.value),repairOfTaskId:repairOf.value,changeReason:reason.value,promptAdjustment:adjustment.value};const fingerprint=JSON.stringify({...request,form,anchors:state.value?.anchors?.id});if(!generationKeys.has(fingerprint))generationKeys.set(fingerprint,crypto.randomUUID());request.idempotencyKey=generationKeys.get(fingerprint);await props.api('/api/character-workshop/generate',{method:'POST',body:JSON.stringify(request)});seed.value++;await refresh()})}
async function collect(id){await act(async()=>{await props.api('/api/character-workshop/'+person.value+'/collect',{method:'POST',body:JSON.stringify({taskId:id||Number(taskId.value),view:view.value,framing:framing.value,changeReason:reason.value})});await refresh()})}
async function review(r,decision){await act(async()=>{if(!human.value||!note.value.trim())throw new Error('请确认由人工检查原图，并填写具体结论');await props.api(`/api/characters/${person.value}/references/${r.id}/review`,{method:'POST',body:JSON.stringify({decision,note:note.value})});human.value=false;await refresh();emit('changed')})}
async function anchors(){await act(async()=>{await props.api('/api/character-workshop/'+person.value+'/anchors',{method:'POST',body:JSON.stringify({identityId:identity.value,outfitId:outfit.value||0,idempotencyKey:crypto.randomUUID()})});await refresh()})}
async function freeze(){await act(async()=>{const workflows=await props.api('/api/workflows');const w=workflows.find(w=>w.fileName==='minimax_h3_local_i2v_api.json');await props.api('/api/character-library/'+person.value+'/versions',{method:'POST',body:JSON.stringify({label:label.value,outfit:form.clothes,bodyDescription:form.bodyRatio,profile:'baseline480',workflowId:w?.id,referencePack:'basic-nine-v1',freezeProvenance:true,requireReviewed:true,references:basicSlots.map(([v,f])=>({referenceId:choices[v+':'+f],view:v,framing:f})),note:'九图逐槽选择并经人工审核；保存设定、来源和审核快照'})});emit('changed')})}
watch(()=>props.initialCharacterId,id=>{if(id){person.value=id;act(selected)}})
let timer;onMounted(()=>{act(async()=>{await load();if(props.initialCharacterId){person.value=props.initialCharacterId;await selected()}});timer=setInterval(()=>{if(!busy.value&&person.value)refresh().catch(e=>error.value=e.message)},7000)});onBeforeUnmount(()=>clearInterval(timer))
</script>
<template><section class="workshop panel">
  <h2>人物创建与定型</h2><p>人物设定 → 候选近照 → 人工确认身份 → 正面全身造型 → 九图审核 → 冻结造型版本。同一人物换衣服保存新造型版本。</p>
  <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/>
  <div class="controls"><el-select v-model="person" placeholder="选择草稿人物" @change="()=>act(selected)" aria-label="草稿人物"><el-option v-for="p in people" :key="p.id" :value="p.id" :label="p.name"/></el-select><el-button @click="person=null;state=null;keys.forEach(k=>form[k]='')">新人物</el-button><el-button @click="()=>act(refresh)">刷新候选</el-button></div>
  <el-form label-position="top" class="facts"><el-form-item label="所属项目"><el-select v-model="form.projectId" aria-label="人物所属项目"><el-option v-for="p in projects" :value="p.id" :key="p.id" :label="p.name"/></el-select></el-form-item><el-form-item v-for="k in keys" :key="k" :label="labels[k]"><el-input v-model="form[k]" :aria-label="labels[k]" :type="k==='fixedPrompt'||k==='immutableTraits'?'textarea':'text'"/></el-form-item></el-form>
  <el-button type="primary" :loading="busy" @click="save">保存人物设定</el-button>
  <template v-if="person"><div class="controls"><el-input-number v-model="seed" :min="0" :max="9007199254740991" aria-label="候选种子"/><el-button :disabled="busy" @click="generate('identity')">生成一张身份候选</el-button><el-button :disabled="busy||!state?.anchors" @click="generate('outfit')">派生正面全身造型</el-button></div>
  <div class="controls"><el-select v-model="identity" placeholder="已批准的正面身份锚点" aria-label="身份锚点"><el-option v-for="r in refs.filter(r=>r.kind==='front-closeUp')" :key="r.id" :value="r.id" :label="`#${r.id} · ${r.metadata.humanReviewStatus}`"/></el-select><el-select v-model="outfit" clearable placeholder="已批准的正面全身基准" aria-label="造型基准"><el-option v-for="r in refs.filter(r=>r.kind==='front-fullBody')" :key="r.id" :value="r.id" :label="`#${r.id} · ${r.metadata.humanReviewStatus}`"/></el-select><el-button :disabled="busy||!identity" @click="anchors">确认身份/造型基准</el-button></div>
  <p>方向按画面约定：鼻尖朝画面左/右；前侧需保留双眼和斜前方身体。背面主要检查发型、服装与体型。</p>
  <details v-if="state?.prompts?.length"><summary>查看九图统一生成规则 · {{state.promptPolicy}}</summary><p>包含面部与头颈、手臂手指、躯干腿脚及当前方向的遮挡规则。生成后仍须逐张检查。</p><details v-for="p in state.prompts" :key="p.view+p.framing"><summary>{{viewNames[p.view]}} · {{framingNames[p.framing]}}</summary><pre>{{p.prompt}}</pre></details></details>
  <div class="controls"><el-select v-model="slot" aria-label="补图槽位"><el-option v-for="[v,f] in basicSlots" :key="v+f" :value="v+':'+f" :label="viewNames[v]+' · '+framingNames[f]"/></el-select><el-input-number v-model="repairOf" :min="1" controls-position="right" placeholder="原失败任务" aria-label="原失败任务"/><el-input v-model="reason" placeholder="修复或纠正用途的具体原因" aria-label="定向修复原因"/><el-button :disabled="busy||!state?.anchors?.payload.outfit" @click="generate('slot')">只生成/修复此槽位</el-button></div>
  <p>每个失败槽位最多两次定向修复；先拒绝失败图，再提供来源任务、不同种子和改变原因。</p>
  <el-input v-model="adjustment" type="textarea" aria-label="候选定向提示词" placeholder="针对失败项实际改变的提示词；不改变已确认的人物身份和造型"/>
  <div class="controls"><el-input-number v-model="taskId" :min="1" aria-label="来源任务ID"/><el-select v-model="view" aria-label="收集候选方向"><el-option v-for="v in ['front','threeQuarterLeft','threeQuarterRight','left','back','right']" :value="v" :key="v" :label="viewNames[v]"/></el-select><el-select v-model="framing" aria-label="收集候选景别"><el-option v-for="f in ['closeUp','fullBody']" :key="f" :value="f" :label="framingNames[f]"/></el-select><el-button :disabled="busy||!taskId" @click="collect()">收集真实任务输出</el-button></div>
  <el-table :data="state?.tasks||[]" size="small"><el-table-column prop="id" label="生成任务" width="90"/><el-table-column prop="status" label="状态" width="120"/><el-table-column label="用途"><template #default="{row}">{{row.input.parameters.characterWorkbench.request.view}} · {{row.input.parameters.characterWorkbench.request.framing}}</template></el-table-column><el-table-column prop="error" label="失败原因"/><el-table-column width="120"><template #default="{row}"><el-button v-if="row.status==='Succeeded'" @click="taskId=row.id;view=row.input.parameters.characterWorkbench.request.view;framing=row.input.parameters.characterWorkbench.request.framing;collect(row.id)">收集候选</el-button></template></el-table-column></el-table>
  <div class="controls"><el-checkbox v-model="human">我已人工检查原图、方向、身份与造型</el-checkbox><el-input v-model="note" placeholder="具体审核结论（无身份分数）" aria-label="素材审核说明"/></div>
  <div class="candidates"><article v-for="r in refs" :key="r.id"><button class="photo" @click="zoom=r"><img v-if="r.available" :src="media(r.assetPath)" :alt="candidateLabel(r)" loading="lazy"/></button><strong>{{candidateLabel(r)}}</strong><p>{{r.metadata.humanReviewStatus}} · 来源任务 {{r.metadata.workbench?.taskId||'旧版记录'}} · 方向待审</p><el-button :disabled="busy||!human" @click="review(r,'Approved')">批准素材</el-button><el-button :disabled="busy||!human" type="danger" plain @click="review(r,'Rejected')">拒绝</el-button><details><summary>来源、参数与纠正记录</summary><pre>{{r.metadata}}</pre></details></article></div>
  <h3>九图逐槽选择与入库</h3><p>完整度与内容审核分别检查。仅已批准素材可以冻结新版；旧版本保持可读。</p><div class="facts"><label v-for="[v,f] in basicSlots" :key="v+f">{{viewNames[v]}} · {{framingNames[f]}}<el-select v-model="choices[v+':'+f]" :aria-label="'入库 '+viewNames[v]+' '+framingNames[f]"><el-option v-for="r in refs.filter(r=>r.kind===v+'-'+f)" :key="r.id" :value="r.id" :label="`#${r.id} · ${r.metadata.humanReviewStatus}`"/></el-select></label></div><div class="controls"><el-input v-model="label" placeholder="造型名称" aria-label="造型名称"/><el-button type="primary" :disabled="busy||!complete" @click="freeze">冻结已审核九图版本</el-button></div>
  </template><el-dialog :model-value="!!zoom" @update:model-value="v=>{if(!v)zoom=null}" title="原图检查与候选比较" width="94%" destroy-on-close><img v-if="zoom" class="original" :src="media(zoom.assetPath)" :alt="zoom.kind"/><pre v-if="zoom">{{zoom.metadata}}</pre></el-dialog>
</section></template>
<style scoped>.workshop{padding:20px;margin-bottom:20px}.controls{display:flex;flex-wrap:wrap;gap:10px;margin:16px 0}.controls .el-input,.controls .el-select{width:260px}.facts{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px}.candidates{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px}.candidates article{padding:10px;border:1px solid #d6dce8;border-radius:10px}.photo{border:0;background:none;width:100%;cursor:zoom-in}.photo img{width:100%;aspect-ratio:16/9;object-fit:contain}.original{width:100%;object-fit:contain}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:400px;overflow:auto;font-size:12px}</style>
